  Serial.begin(115200);
  pinMode(relayPin, OUTPUT);

  // Memulai koneksi ke Server Blynk
  Blynk.begin(BLYNK_AUTH_TOKEN, ssid, pass);
}

void loop() {
  // Menjaga koneksi ESP32 tetap sinkron dengan server Blynk
  Blynk.run();
}

// Fungsi ini dipanggil otomatis ketika tombol Virtual V1 di Aplikasi Blynk ditekan
BLYNK_WRITE(V1) {
  int pinValue = param.asInt(); // Membaca status (0 atau 1) dari HP

  digitalWrite(relayPin, pinValue); // Mengubah status Relay/LED sesuai dari HP
}
```

# 3. Praktek Implementasi

## A. Algoritma (Cara Kerja)
1. Baca jarak dari sensor ultrasonik.
2. Jika jarak <= 20 cm, perintahkan servo bergerak ke 90 derajat (Buka Tutup).
3. Tunggu selama 3 detik agar pengguna bisa membuang sampah.
4. Perintahkan servo kembali ke 0 derajat (Tutup).
5. Jika jarak > 20 cm, pastikan servo tetap di 0 derajat.

## B. Kebutuhan Komponen
- **Kontroler:** Arduino Uno
- **Sensor:** Ultrasonik HC-SR04
- **Aktuator:** Motor Servo Micro SG90
- **Fisik:** Tempat sampah kecil berpenutup engsel, Kawat/Tali penghubung.

## C. Kode Program

```cpp
#include <Servo.h>

const int trigPin = 9;
const int echoPin = 10;
const int servoPin = 3;

Servo binServo;
long duration;
int distance;

void setup() {
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
  binServo.attach(servoPin);

  binServo.write(0); // Tutup tempat sampah sejak awal
  delay(1000);
}

void loop() {
  // Menghasilkan gelombang ultrasonik
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  // Membaca pantulan
  duration = pulseIn(echoPin, HIGH);
  distance = duration * 0.034 / 2;

  // Logika Buka Tutup
  if (distance > 0 && distance <= 20) {
    binServo.write(90); // Buka
    delay(3000);        // Tahan 3 detik
  } else {
    binServo.write(0);  // Tutup
  }

  delay(100); // Stabilitas pembacaan
}
```

# 3. Praktek Implementasi

## A. Algoritma (Cara Kerja)
1. Inisialisasi SPI, RFID, dan LCD.
2. Tampilkan "Tempelkan Kartu" di LCD.
3. Tunggu hingga kartu dideteksi.
4. Baca UID kartu.
5. Jika UID sama dengan "A3 B4 C5 D6" (Ganti dengan UID asli Anda):
   - Tampilkan "Akses Diterima" di LCD.
   - Nyalakan Relay (Pintu Terbuka) selama 5 detik.
   - Matikan Relay kembali (Pintu Terkunci).
6. Jika UID salah:
   - Tampilkan "Akses Ditolak".
   - Tunggu 2 detik, lalu kembali ke langkah 2.

## B. Kebutuhan Komponen
- **Kontroler:** Arduino Uno
- **Sensor:** RFID RC522 + Tag
- **Aktuator:** Modul Relay, Selenoid Door Lock 12V (Opsional, perlu adaptor tambahan), LCD 16x2 I2C.

## C. Kode Program

```cpp
#include <SPI.h>
#include <MFRC522.h>
#include <Wire.h>
#include <LiquidCrystal_I2C.h>

#define RST_PIN 9
#define SS_PIN  10
const int relayPin = 7;

MFRC522 mfrc522(SS_PIN, RST_PIN);
LiquidCrystal_I2C lcd(0x27, 16, 2);

// GANTI DENGAN UID KARTU ANDA (Gunakan huruf KAPITAL tanpa spasi)
String registeredCard = "A3B4C5D6"; 

void setup() {
  SPI.begin();
  mfrc522.PCD_Init();

  pinMode(relayPin, OUTPUT);
  digitalWrite(relayPin, HIGH); // Relay Mati (Terkunci)

  lcd.begin();
  lcd.backlight();
  lcd.setCursor(0, 0);
  lcd.print(" Tempelkan Tag  ");
}

void loop() {
  if ( ! mfrc522.PICC_IsNewCardPresent() || ! mfrc522.PICC_ReadCardSerial()) {
    return;
  }

  String uidStr = "";
  for (byte i = 0; i < mfrc522.uid.size; i++) {
     uidStr += String(mfrc522.uid.uidByte[i] < 0x10 ? "0" : "");
     uidStr += String(mfrc522.uid.uidByte[i], HEX);
  }
  uidStr.toUpperCase();

  if (uidStr == registeredCard) {
    lcd.clear();
    lcd.print("Akses Diterima!");
    digitalWrite(relayPin, LOW); // Relay Hidup (Pintu Buka)
    delay(5000); // Buka selama 5 detik
    digitalWrite(relayPin, HIGH); // Kunci kembali
  } else {
    lcd.clear();
    lcd.print("Akses Ditolak!");
    delay(2000);
  }

  // Kembalikan ke tampilan awal
  lcd.clear();
  lcd.print(" Tempelkan Tag  ");
}
```

# 3. Praktek Implementasi

## A. Algoritma (Cara Kerja)
1. Hubungkan ESP32 ke Wi-Fi dan Server Blynk.
2. Setiap 5 detik, baca data Suhu dan Kelembaban dari DHT11.
3. Kirim data Suhu ke Virtual Pin V0 di Blynk.
4. Kirim data Kelembaban ke Virtual Pin V1 di Blynk.
5. Di aplikasi Blynk HP, tambahkan dua widget *Gauge*, atur inputnya ke V0 (0-100) dan V1 (0-100).

## B. Kebutuhan Komponen
- **Kontroler:** Board NodeMCU ESP32
- **Sensor:** Modul DHT11
- **Platform:** Aplikasi Blynk & Jaringan Wi-Fi

## C. Kode Program

*(Catatan: Pastikan library Blynk dan DHT sudah terinstal)*

```cpp
#define BLYNK_TEMPLATE_ID "TEMPLATE_ID_ANDA"
#define BLYNK_DEVICE_NAME "Stasiun Cuaca IoT"
#define BLYNK_AUTH_TOKEN  "AUTH_TOKEN_RAHASIA_ANDA"

#include <WiFi.h>
#include <WiFiClient.h>
#include <BlynkSimpleEsp32.h>
#include "DHT.h"

char ssid[] = "NAMA_WIFI";
char pass[] = "PASSWORD_WIFI";

#define DHTPIN 4
#define DHTTYPE DHT11
DHT dht(DHTPIN, DHTTYPE);

// Timer untuk menghindari delay() yang memblokir Blynk
BlynkTimer timer;

void sendSensor() {
  float h = dht.readHumidity();
  float t = dht.readTemperature();

  if (isnan(h) || isnan(t)) {
    Serial.println("Gagal membaca dari sensor DHT!");
    return;
  }

  // Mengirim data ke Aplikasi Blynk (HP)
  Blynk.virtualWrite(V0, t); // V0 untuk Suhu
  Blynk.virtualWrite(V1, h); // V1 untuk Kelembaban
}

void setup() {
  Serial.begin(115200);
  dht.begin();
  Blynk.begin(BLYNK_AUTH_TOKEN, ssid, pass);

  // Memanggil fungsi sendSensor setiap 5000ms (5 detik)
  timer.setInterval(5000L, sendSensor);
}

void loop() {
  Blynk.run();
  timer.run(); // Menjalankan timer Blynk
}
```

# 3. Praktek Implementasi

## A. Algoritma (Cara Kerja)
1. Atur Pin Sensor Cahaya sebagai INPUT dan Pin Buzzer sebagai OUTPUT.
2. Baca status Sensor. (Asumsi: Modul LDR akan memberikan logika HIGH (1) saat lingkungan menjadi GELAP / laser terputus).
3. Jika status HIGH (Laser terputus oleh maling):
   - Bunyikan Buzzer dengan nada tinggi.
   - Tunggu sebentar.
   - Bunyikan Buzzer dengan nada rendah (efek sirine ninu-ninu).
4. Jika status LOW (Aman, sinar terang mengenai sensor):
   - Matikan Buzzer.

## B. Kebutuhan Komponen
- **Kontroler:** Arduino Uno
- **Sensor:** Modul Sensor Cahaya LDR (Light Dependent Resistor)
- **Aktuator:** Piezo Buzzer
- **Tambahan:** Senter Kecil atau Laser Pointer (sebagai sumber cahaya).

## C. Kode Program

```cpp
const int ldrPin = 4;
const int buzzerPin = 8;

void setup() {
  pinMode(ldrPin, INPUT);
  pinMode(buzzerPin, OUTPUT);
}

void loop() {
  int sensorState = digitalRead(ldrPin);

  // Jika laser terputus (Cahaya Gelap / Status HIGH)
  if (sensorState == HIGH) {
    // Bunyikan Sirine (Efek naik turun)
    tone(buzzerPin, 1000); // Nada Tinggi (1000 Hz)
    delay(200);
    tone(buzzerPin, 500);  // Nada Rendah (500 Hz)
    delay(200);
  } 
  // Jika laser menyala normal (Cahaya Terang / Status LOW)
  else {
    noTone(buzzerPin); // Matikan suara
    delay(100);
  }
}
```
